package steps

import "testing"

func TestV116ModuleOptionRenames(t *testing.T) {
	t.Parallel()
	runStepCases(t, 116, []stepCase{
		{"Markets layout on an Overlay page, order kept", `{"Overlay":{"items":[{"id":"p","layout":[{"type":"Markets","properties":{"layout":"tiles","range":"5d"}}]}]}}`,
			`{"Overlay":{"items":[{"id":"p","layout":[{"type":"Markets","properties":{"style":"tiles","range":"5d"}}]}]}}`, true},
		{"Markets on the lock screen", `{"Lockscreen":{"layout":[{"type":"Markets","properties":{"layout":"focus"}}]}}`,
			`{"Lockscreen":{"layout":[{"type":"Markets","properties":{"style":"focus"}}]}}`, true},
		{"Cheatsheet view in a Menu", `{"Menus":{"items":[{"id":"m","layout":[{"type":"Cheatsheet","properties":{"view":"keyboard"}}]}]}}`,
			`{"Menus":{"items":[{"id":"m","layout":[{"type":"Cheatsheet","properties":{"style":"keyboard"}}]}]}}`, true},
		{"Agenda maxEvents on the desktop", `{"Desktop":{"modules":[{"type":"Agenda","properties":{"maxEvents":5}}]}}`,
			`{"Desktop":{"modules":[{"type":"Agenda","properties":{"count":5}}]}}`, true},
		{"Favourites true becomes auto", `{"Desktop":{"modules":[{"type":"Favourites","properties":{"showLabels":true}}]}}`,
			`{"Desktop":{"modules":[{"type":"Favourites","properties":{"labels":"auto"}}]}}`, true},
		{"Favourites false becomes hide", `{"Desktop":{"modules":[{"type":"Favourites","properties":{"showLabels":false}}]}}`,
			`{"Desktop":{"modules":[{"type":"Favourites","properties":{"labels":"hide"}}]}}`, true},
		{"Favourites a string is removed", `{"Desktop":{"modules":[{"type":"Favourites","properties":{"showLabels":"yes"}}]}}`,
			`{"Desktop":{"modules":[{"type":"Favourites","properties":{}}]}}`, true},
		{"Favourites with labels set drops showLabels", `{"Desktop":{"modules":[{"type":"Favourites","properties":{"showLabels":true,"labels":"show"}}]}}`,
			`{"Desktop":{"modules":[{"type":"Favourites","properties":{"labels":"show"}}]}}`, true},
		{"Login true becomes center in the greeter", `{"Greeter":{"layout":[{"type":"Login","properties":{"centered":true,"userField":"typed"}}]}}`,
			`{"Greeter":{"layout":[{"type":"Login","properties":{"alignment":"center","userField":"typed"}}]}}`, true},
		{"Password false becomes left on the lock screen", `{"Lockscreen":{"layout":[{"type":"Password","properties":{"centered":false}}]}}`,
			`{"Lockscreen":{"layout":[{"type":"Password","properties":{"alignment":"left"}}]}}`, true},
		{"Password a string is removed", `{"Lockscreen":{"layout":[{"type":"Password","properties":{"centered":"yes"}}]}}`,
			`{"Lockscreen":{"layout":[{"type":"Password","properties":{}}]}}`, true},
		{"Login with alignment set drops centered", `{"Greeter":{"layout":[{"type":"Login","properties":{"centered":true,"alignment":"right"}}]}}`,
			`{"Greeter":{"layout":[{"type":"Login","properties":{"alignment":"right"}}]}}`, true},
		{"a Greeting centered is untouched", `{"Greeter":{"layout":[{"type":"Greeting","properties":{"centered":true}}]}}`,
			`{"Greeter":{"layout":[{"type":"Greeting","properties":{"centered":true}}]}}`, false},
		{"both old and new keys of a rename", `{"Desktop":{"modules":[{"type":"Agenda","properties":{"maxEvents":5,"count":9}}]}}`,
			`{"Desktop":{"modules":[{"type":"Agenda","properties":{"count":9}}]}}`, true},
		{"already migrated", `{"Desktop":{"modules":[{"type":"Markets","properties":{"style":"list"}},{"type":"Favourites","properties":{"labels":"hide"}}]}}`,
			`{"Desktop":{"modules":[{"type":"Markets","properties":{"style":"list"}},{"type":"Favourites","properties":{"labels":"hide"}}]}}`, false},
		{"a Markets bar widget is untouched", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Markets","properties":{"layout":"x"}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Markets","properties":{"layout":"x"}}]}]}}`, false},
		{"properties not an object", `{"Desktop":{"modules":[{"type":"Markets","properties":3}]}}`,
			`{"Desktop":{"modules":[{"type":"Markets","properties":3}]}}`, false},
		{"Markets widget showPortfolio", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Markets","properties":{"showPortfolio":true,"range":"5d"}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Markets","properties":{"showHoldings":true,"range":"5d"}}]}]}}`, true},
		{"Network widget showVpn false in place", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Network","properties":{"showDevice":true,"showVpn":false,"vpnColor":"x"}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Network","properties":{"showDevice":true,"showVpnLock":false,"vpnColor":"x"}}]}]}}`, true},
		{"widgets inside a group", `{"Bars":{"items":[{"left":[{"type":"Group","properties":{"widgets":[{"type":"Network","properties":{"showVpn":true}},{"type":"Markets","properties":{"showPortfolio":false}}]}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Group","properties":{"widgets":[{"type":"Network","properties":{"showVpnLock":true}},{"type":"Markets","properties":{"showHoldings":false}}]}}]}]}}`, true},
		{"a Network module showVpn is untouched", `{"Desktop":{"modules":[{"type":"Network","properties":{"showVpn":true}}]}}`,
			`{"Desktop":{"modules":[{"type":"Network","properties":{"showVpn":true}}]}}`, false},
		{"Workspaces widget labels in place", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Workspaces","properties":{"labels":"dots","spacing":2}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Workspaces","properties":{"cellLabels":"dots","spacing":2}}]}]}}`, true},
		{"Workspaces widget with cellLabels set drops labels", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Workspaces","properties":{"labels":"dots","cellLabels":"none"}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Workspaces","properties":{"cellLabels":"none"}}]}]}}`, true},
		{"a QuickActions module labels is untouched", `{"Desktop":{"modules":[{"type":"QuickActions","properties":{"labels":"show"}}]}}`,
			`{"Desktop":{"modules":[{"type":"QuickActions","properties":{"labels":"show"}}]}}`, false},
		{"bar widgets already migrated", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Workspaces","properties":{"cellLabels":"dots"}},{"type":"Network","properties":{"showVpnLock":true}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Workspaces","properties":{"cellLabels":"dots"}},{"type":"Network","properties":{"showVpnLock":true}}]}]}}`, false},
		{"SystemStats booleans become metrics in place", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"appearance":{},"showCpu":false,"showMemory":true,"showTemp":false,"showGpu":true,"showDisk":true,"interval":2000}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"appearance":{},"metrics":["mem","gpu","disk"],"interval":2000}}]}]}}`, true},
		{"SystemStats only showGpu", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"showGpu":true}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"metrics":["cpu","mem","cpuTemp","gpu"]}}]}]}}`, true},
		{"SystemStats all false", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"showCpu":false,"showMemory":false,"showTemp":false,"showGpu":false,"showDisk":false}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"metrics":[]}}]}]}}`, true},
		{"SystemStats a non-boolean counts as its default", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"showCpu":"yes","showGpu":1}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"metrics":["cpu","mem","cpuTemp"]}}]}]}}`, true},
		{"SystemStats with metrics set drops the booleans", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"showCpu":false,"metrics":["disk"],"showDisk":true}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"metrics":["disk"]}}]}]}}`, true},
		{"SystemStats none present", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"interval":2000}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"SystemStats","properties":{"interval":2000}}]}]}}`, false},
		{"a SystemStats widget inside a group", `{"Bars":{"items":[{"left":[{"type":"Group","properties":{"widgets":[{"type":"SystemStats","properties":{"showDisk":true}}]}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Group","properties":{"widgets":[{"type":"SystemStats","properties":{"metrics":["cpu","mem","cpuTemp","disk"]}}]}}]}]}}`, true},
		{"a SystemGraphs module is untouched", `{"Desktop":{"modules":[{"type":"SystemGraphs","properties":{"showCpu":true,"metrics":["cpu"]}}]}}`,
			`{"Desktop":{"modules":[{"type":"SystemGraphs","properties":{"showCpu":true,"metrics":["cpu"]}}]}}`, false},
		{"LockKeys booleans become shows in place", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"hideWhenOff":true,"showCaps":true,"showNum":true,"showScroll":false,"boxes":"each"}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"hideWhenOff":true,"shows":["capsLock","numLock"],"boxes":"each"}}]}]}}`, true},
		{"LockKeys only showScroll", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"showScroll":true}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"shows":["capsLock","scrollLock"]}}]}]}}`, true},
		{"LockKeys all false", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"showCaps":false,"showNum":false,"showScroll":false}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"shows":[]}}]}]}}`, true},
		{"LockKeys a non-boolean counts as its default", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"showCaps":"yes","showNum":1}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"shows":["capsLock"]}}]}]}}`, true},
		{"LockKeys with shows set drops the booleans", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"showCaps":false,"shows":["numLock"],"showNum":true}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"shows":["numLock"]}}]}]}}`, true},
		{"LockKeys none present", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"hideWhenOff":true}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"LockKeys","properties":{"hideWhenOff":true}}]}]}}`, false},
		{"Privacy booleans become shows in place", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"showMic":true,"showScreen":false,"showCamera":true,"ignoreApps":["cava"]}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"shows":["micUse","camera"],"ignoreApps":["cava"]}}]}]}}`, true},
		{"Privacy only showCamera false", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"showCamera":false}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"shows":["micUse","screenShare"]}}]}]}}`, true},
		{"Privacy all false", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"showMic":false,"showScreen":false,"showCamera":false}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"shows":[]}}]}]}}`, true},
		{"Privacy a non-boolean counts as its default", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"showMic":"no","showScreen":false}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"shows":["micUse","camera"]}}]}]}}`, true},
		{"Privacy with shows set drops the booleans", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"showMic":false,"shows":["camera"]}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"shows":["camera"]}}]}]}}`, true},
		{"Privacy none present", `{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"ignoreApps":[]}}]}]}}`,
			`{"Bars":{"items":[{"id":"b","widgets":[{"type":"Privacy","properties":{"ignoreApps":[]}}]}]}}`, false},
		{"OSD LockKeys and Privacy systems are untouched", `{"OSD":{"systems":[{"type":"LockKeys","showCaps":true},{"type":"Privacy","showMic":true}]}}`,
			`{"OSD":{"systems":[{"type":"LockKeys","showCaps":true},{"type":"Privacy","showMic":true}]}}`, false},
		{"Overlay not an object", `{"Overlay":"x"}`, `{"Overlay":"x"}`, false},
		{"no sections", `{}`, `{}`, false},
	})
}
